# 二分查找算法
def binary_search(arr, target):
    left = 0
    right = len(arr) - 1

    while left <= right:
        mid = (left + right) // 2

        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return -1

# 测试二分查找
sorted_array = [2, 5, 8, 12, 16, 23, 38, 45, 56, 67, 78]
target = 23

result = binary_search(sorted_array, target)
if result != -1:
    print(f"元素 {target} 在索引 {result} 处")
else:
    print(f"元素 {target} 不在数组中")
